'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, lens='全部', lastTrigger;
const list = xs => `<ul>${xs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
function renderQuestions(){const term=$('#search').value.trim().toLocaleLowerCase();const filtered=data.questions.filter(q=>(lens==='全部'||q.lens===lens)&&JSON.stringify(q).toLocaleLowerCase().includes(term));$('#results').textContent=`显示 ${filtered.length} 个问题 / 共 ${data.questions.length} 个；状态表示研究进度，不代表结论可信度。`;$('#question-list').innerHTML=filtered.length?filtered.map(q=>`<article class="question-card"><div class="card-top"><span>${esc(q.id)} · ${esc(q.lens)}</span><span class="badge">${esc(q.state)}</span></div><h3>${esc(q.title)}</h3><p>${esc(q.background)}</p><div class="tags">${q.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><button type="button" data-question="${esc(q.id)}">查看证据与不同选项 ↗</button></article>`).join(''):'<p class="empty">没有匹配的问题。试试其他关键词或切回全部。</p>'}
function showQuestion(id,trigger){const q=data.questions.find(q=>q.id===id);if(!q)return;lastTrigger=trigger;$('#detail-content').innerHTML=`<p class="eyebrow">${esc(q.id)} / ${esc(q.lens)} / ${esc(q.state)}</p><h2 id="detail-title">${esc(q.title)}</h2><p>${esc(q.background)}</p><p class="example">${esc(q.scenario)}</p><h3>已核实的资料事实</h3>${list(q.known)}<h3>仍然未知</h3>${list(q.unknown)}<h3>可比较的选项 · 本站研究提案</h3><div class="options">${q.options.map(o=>`<div class="option"><h4>${esc(o.title)}</h4><p>${esc(o.action)}</p><p><b>条件：</b>${esc(o.condition)}</p><p><b>代价与例外：</b>${esc(o.cost)}</p></div>`).join('')}</div><h3>当前判断 · 本站分析</h3><p>${esc(q.judgment)}</p><h3>什么会改变这个判断？</h3><p>${esc(q.change_if)}</p><h3>下一步取证</h3><p>${esc(q.next)}</p><h3>相关原始来源</h3><div class="source-links">${q.refs.map(id=>{const s=data.sources.find(s=>s.id===id);return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.id)} ${esc(s.title)} ↗</a>`}).join('')}</div><p class="muted">实质修订：${esc(q.updated)}。招聘描述和学习路线不等于实际效果验证。</p>`;if(!$('#detail').open)$('#detail').showModal();}
function render(){ $('#edition').textContent=`初版 ${data.version} · 内容核读 ${data.updated} · 非实时资讯`;renderQuestions();$('#signals').innerHTML=data.signals.map(s=>`<article class="signal"><small>${esc(s.id)} · ${esc(s.status)}</small><b>${esc(s.title)}</b><p>${esc(s.note)}</p></article>`).join('');$('#role-list').innerHTML=data.roles.map(r=>`<article class="role"><b>${esc(r.name)}</b><small>${esc(r.kind)}</small><p>${esc(r.text)}</p></article>`).join('');$('#scenario-list').innerHTML=data.scenarios.map(s=>`<article class="scenario"><span>${esc(s.id)}</span><h3>${esc(s.title)}</h3><p><label>如果</label>${esc(s.premise)}</p><p><label>可选行动</label>${esc(s.action)}</p><p><label>观察什么</label>${esc(s.watch)}</p></article>`).join('');$('#source-list').innerHTML=data.sources.map(s=>`<article class="source" id="source-${esc(s.id)}"><span class="source-id">${esc(s.id)}</span><div><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(s.title)} ↗</b></a><small>${esc(s.publisher)} · ${esc(s.kind)}</small><small>核读：${esc(s.checked)} · 首发日期：${s.published?esc(s.published):'未核实'}</small></div><div><p>${esc(s.summary)}</p><p class="limit">边界：${esc(s.boundary)}</p></div></article>`).join('');$('#history').innerHTML=data.history.map(h=>`<article class="event"><small>${esc(h.date)}</small><h3>${esc(h.title)}</h3><p>${esc(h.text)}</p></article>`).join('');}
document.querySelectorAll('[data-lens]').forEach(b=>b.addEventListener('click',()=>{lens=b.dataset.lens;document.querySelectorAll('[data-lens]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderQuestions()}));$('#search').addEventListener('input',renderQuestions);$('#question-list').addEventListener('click',e=>{const b=e.target.closest('[data-question]');if(b)showQuestion(b.dataset.question,b)});$('#close-detail').addEventListener('click',()=>$('#detail').close());$('#detail').addEventListener('close',()=>{if(lastTrigger&&lastTrigger.isConnected)lastTrigger.focus()});$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});fetch('./observatory.json').then(r=>{if(!r.ok)throw new Error('data');return r.json()}).then(d=>{data=d;render()}).catch(()=>{$('#question-list').innerHTML='<p class="empty">研究数据暂时无法加载，请刷新页面或查看 GitHub 文档。</p>'});
